//! MinAxes and MaxAxes, and the FindFrame matches they allow, checked
//! against the C library.
//!
//! `min_max_axes_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/min_max_axes_probe.c`. An unset MinAxes defaults to
//! Naxes but no more than a set MaxAxes, an unset MaxAxes to Naxes but no
//! less than a set MinAxes, and setting either moves a set value of the other
//! to stay consistent (frame.c `DefaultMinAxes`, `DefaultMaxAxes`,
//! `ConsistentMinAxes`, `ConsistentMaxAxes`). CmpFrame defaults to 0 and
//! 1000000 instead (cmpframe.c `GetMinAxes`, `GetMaxAxes`).

#[path = "min_max_axes_oracle/cases.rs"]
mod cases;

use ast_core::frames::{BasicFrameBuilder, CmpFrame, Frame, SkyFrame};

fn make(class: &str) -> Box<dyn Frame> {
    match class {
        "Frame2" => Box::new(BasicFrameBuilder::new(2).build().unwrap()),
        "SkyFrame" => Box::new(SkyFrame::unset_system()),
        "CmpFrame" => Box::new(CmpFrame::new(
            Box::new(BasicFrameBuilder::new(1).build().unwrap()),
            Box::new(BasicFrameBuilder::new(1).build().unwrap()),
        )),
        other => panic!("unknown class {other}"),
    }
}

/// Apply a probe settings string: `;`-separated `MinAxes=n`, `MaxAxes=n`,
/// `-MinAxes` (clear) or `-MaxAxes`.
fn apply(f: &mut dyn Frame, settings: &str) {
    for tok in settings.split(';').filter(|t| !t.is_empty()) {
        match tok {
            "-MinAxes" => f.clear_min_axes().unwrap(),
            "-MaxAxes" => f.clear_max_axes().unwrap(),
            _ => {
                let (name, value) = tok.split_once('=').unwrap();
                let n: usize = value.parse().unwrap();
                match name {
                    "MinAxes" => f.set_min_axes(n).unwrap(),
                    "MaxAxes" => f.set_max_axes(n).unwrap(),
                    other => panic!("unknown attribute {other}"),
                }
            }
        }
    }
}

#[test]
fn min_max_axes_match_the_c_library() {
    let mut failures = Vec::new();
    for &(class, settings, min, max, test_min, test_max) in cases::AXES_CASES {
        let mut f = make(class);
        apply(f.as_mut(), settings);
        let got = (
            f.min_axes(),
            f.max_axes(),
            f.test_min_axes(),
            f.test_max_axes(),
        );
        if got != (min, max, test_min, test_max) {
            failures.push(format!(
                "{class} [{settings}]: got {got:?}, C gives {:?}",
                (min, max, test_min, test_max)
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn find_frame_matches_the_c_library() {
    let mut failures = Vec::new();
    for &(settings, naxes, matched) in cases::FIND_CASES {
        let mut template = BasicFrameBuilder::new(2).build().unwrap();
        apply(&mut template, settings);
        let target = BasicFrameBuilder::new(naxes).build().unwrap();
        let got = target.find_frame_template(&template, "").unwrap().is_some();
        if got != matched {
            failures.push(format!(
                "[{settings}] against {naxes} axes: got {got}, C gives {matched}"
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
